// Build an image from Dockerfile in current directory
docker build -t order-service:v1.0 .

// Run container with port mapping and name
docker run -d -p 8080:8080 --name order-api order-service:v1.0

// List all running containers
docker ps

// View real-time logs from the container
docker logs -f order-api

// Execute shell inside running container for debugging
docker exec -it order-api /bin/bash

// Stop the container gracefully
docker stop order-api

// Remove stopped container
docker rm order-api

// List all images on your machine
docker images

// Remove an image when no longer needed
docker rmi order-service:v1.0

// Pull an image from Docker Hub
docker pull postgres:15

// Standard mapping: host 8080 to container 8080
docker run -d -p 8080:8080 --name order-api order-service:v1.0
// Access at http://localhost:8080

// Avoid port conflict: map host 9090 to container 8080
docker run -d -p 9090:8080 --name customer-api customer-service:v1.0
// Access at http://localhost:9090

// Run Postgres with standard port mapping
docker run -d -p 5432:5432 --name postgres-db postgres:15
// JDBC URL: jdbc:postgresql://localhost:5432/mydb

// Multiple port mappings for app and debug port
docker run -d \
  -p 8080:8080 \
  -p 5005:5005 \
  --name order-api-debug \
  order-service:v1.0
// App at localhost:8080, remote debugger at localhost:5005

// Bind to specific host IP instead of all interfaces
docker run -d -p 127.0.0.1:8080:8080 --name local-only order-service:v1.0
// Only accessible from localhost, not from other machines on network

// View all logs from container named order-api
docker logs order-api

// Follow logs in real time (like tail -f)
docker logs -f order-api

// Show only the last 100 lines
docker logs --tail 100 order-api

// Show logs from the last 10 minutes
docker logs --since 10m order-api

// Combine filters: last 50 lines from past 5 minutes
docker logs --since 5m --tail 50 order-api

// Show logs with timestamps for debugging timing issues
docker logs -t order-api

// View logs from a specific time point
docker logs --since 2024-01-15T14:30:00 order-api

// Follow logs and filter with grep for errors
docker logs -f order-api | grep ERROR

// Save logs to file for analysis
docker logs order-api > order-api-logs.txt

// Check current disk usage before cleanup
docker system df

// Remove all stopped containers, unused images, and build cache
docker system prune -a

// Prune with confirmation prompt (safer)
docker system prune

// Remove only stopped containers
docker container prune

// Remove unused images (not referenced by any container)
docker image prune

// Remove unused images including tagged ones
docker image prune -a

// Remove a specific stopped container
docker rm order-api

// Force remove a running container
docker rm -f order-api

// Remove a specific image
docker rmi order-service:v1.0

// Remove multiple images at once
docker rmi $(docker images -q -f dangling=true)

// Remove all stopped containers with one command
docker container rm $(docker ps -a -q -f status=exited)

// Prune build cache older than 24 hours
docker builder prune --filter until=24h

// Check if container is running
docker ps -a

// View recent logs to see startup errors
docker logs --tail 100 order-api

// Follow logs in real time while reproducing the issue
docker logs -f order-api

// Open interactive shell inside the container
docker exec -it order-api /bin/bash

// Inside container: check environment variables
env | grep SPRING

// Inside container: verify application files exist
ls -la /app

// Inside container: check if process is running
ps aux | grep java

// Exit container shell
exit

// Inspect full container configuration
docker inspect order-api

// Check real-time CPU and memory usage
docker stats order-api

// See running processes inside container
docker top order-api

// Check container's IP address and network
docker inspect -f '{{.NetworkSettings.IPAddress}}' order-api
